import{_ as a,o as n,c as t,aN as e}from"./chunks/framework.D31DlcCL.js";const m="/img/math-triangle-theorems.svg",y=JSON.parse('{"title":"三角形探秘（三）：核心定理与严谨证明的深度解析","description":"几何学不仅是图形的艺术，更是逻辑的巅峰。本文将深度拆解三角形的内角和定理、全等与相似判定、勾股定理等核心命题，通过严谨的推导与图解，带你领略几何证明的魅力。","frontmatter":{"title":"三角形探秘（三）：核心定理与严谨证明的深度解析","date":"2026-02-11T12:00:00.000Z","categories":["杂谈"],"tags":["数学","三角形","几何定理","全等相似","逻辑证明"],"description":"几何学不仅是图形的艺术，更是逻辑的巅峰。本文将深度拆解三角形的内角和定理、全等与相似判定、勾股定理等核心命题，通过严谨的推导与图解，带你领略几何证明的魅力。","cover":"/img/math-triangle-theorems.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/math-triangle-theorems.md","filePath":"posts/math-triangle-theorems.md","lastUpdated":null}'),p={name:"posts/math-triangle-theorems.md"};function i(l,s,r,o,c,h){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="序言-证明-——-几何学的灵魂" tabindex="-1">序言：证明 —— 几何学的灵魂 <a class="header-anchor" href="#序言-证明-——-几何学的灵魂" aria-label="Permalink to &quot;序言：证明 —— 几何学的灵魂&quot;">​</a></h1><p>如果说三角形的分类是它的“外貌”，那么定理和证明就是它的“灵魂”。在数学的历史长河中，三角形的各种性质是被最先系统化证明的。从古希腊的欧几里得到中国古代的赵爽，无数智者通过严密的逻辑，将零散的直观发现凝练成了永恒的定理。</p><p>掌握这些定理，不仅能让你在数学竞赛中如鱼得水，更重要的是，它能训练你“从已知推导出未知”的思维习惯。</p><p><img src="'+m+'" alt="三角形核心定理与严谨证明图解"></p><hr><h1 id="第一篇-基石-——-内角和定理及其深度推导" tabindex="-1">第一篇：基石 —— 内角和定理及其深度推导 <a class="header-anchor" href="#第一篇-基石-——-内角和定理及其深度推导" aria-label="Permalink to &quot;第一篇：基石 —— 内角和定理及其深度推导&quot;">​</a></h1><h2 id="_1-1-定理内容" tabindex="-1">1.1 定理内容 <a class="header-anchor" href="#_1-1-定理内容" aria-label="Permalink to &quot;1.1 定理内容&quot;">​</a></h2><blockquote><p>在欧几里得几何中，任意三角形的三个内角之和恒等于 180°。</p></blockquote><h2 id="_1-2-严谨的几何证明" tabindex="-1">1.2 严谨的几何证明 <a class="header-anchor" href="#_1-2-严谨的几何证明" aria-label="Permalink to &quot;1.2 严谨的几何证明&quot;">​</a></h2><p>很多同学知道结论，但并不清楚它是如何被证明的。最经典的方法是<strong>平行线辅助线法</strong>：</p><ol><li><strong>已知</strong>：△ABC。</li><li><strong>求证</strong>：∠A + ∠B + ∠C = 180°。</li><li><strong>证明步骤</strong>： <ul><li>过顶点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span></span></span></span> 作一条直线 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>l</mi></mrow><annotation encoding="application/x-tex">l</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span>，使得 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>l</mi><mi mathvariant="normal">/</mi><mi mathvariant="normal">/</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">l // BC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span><span class="mord mathrm">/</span><span class="mord mathrm">/</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。</li><li>根据平行线的性质，<strong>内错角相等</strong>：直线 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>l</mi></mrow><annotation encoding="application/x-tex">l</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span> 与边 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 形成的角等于 ∠B，直线 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>l</mi></mrow><annotation encoding="application/x-tex">l</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span> 与边 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 形成的角等于 ∠C。</li><li>显然，这三个角在直线 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>l</mi></mrow><annotation encoding="application/x-tex">l</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span> 上构成了一个<strong>平角</strong>。</li><li>因此，∠A + ∠B + ∠C = 180°。</li></ul></li></ol><h2 id="_1-3-定理的推论" tabindex="-1">1.3 定理的推论 <a class="header-anchor" href="#_1-3-定理的推论" aria-label="Permalink to &quot;1.3 定理的推论&quot;">​</a></h2><ul><li><strong>推论 1</strong>：一个三角形中最多只能有一个钝角或一个直角。</li><li><strong>推论 2</strong>：直角三角形的两个锐角互余。</li><li><strong>推论 3（外角定理）</strong>：三角形的一个外角等于与它不相邻的两个内角之和。</li></ul><hr><h1 id="第二篇-同构-——-全等三角形判定模型" tabindex="-1">第二篇：同构 —— 全等三角形判定模型 <a class="header-anchor" href="#第二篇-同构-——-全等三角形判定模型" aria-label="Permalink to &quot;第二篇：同构 —— 全等三角形判定模型&quot;">​</a></h1><h2 id="_2-1-什么是全等" tabindex="-1">2.1 什么是全等？ <a class="header-anchor" href="#_2-1-什么是全等" aria-label="Permalink to &quot;2.1 什么是全等？&quot;">​</a></h2><p>全等（Congruence）意味着两个三角形可以完全重合。它们是彼此的“克隆体”。</p><h2 id="_2-2-五大判定公理-the-5-postulates" tabindex="-1">2.2 五大判定公理 (The 5 Postulates) <a class="header-anchor" href="#_2-2-五大判定公理-the-5-postulates" aria-label="Permalink to &quot;2.2 五大判定公理 (The 5 Postulates)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">缩写</th><th style="text-align:left;">全称</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SSS</strong></td><td style="text-align:left;">边边边</td><td style="text-align:left;">三条对应边相等，则三角形全等。这是三角形稳定性的数学表现。</td></tr><tr><td style="text-align:left;"><strong>SAS</strong></td><td style="text-align:left;">边角边</td><td style="text-align:left;">两边相等且它们的<strong>夹角</strong>相等。注意：角必须是夹角。</td></tr><tr><td style="text-align:left;"><strong>ASA</strong></td><td style="text-align:left;">角边角</td><td style="text-align:left;">两角相等且它们的<strong>夹边</strong>相等。</td></tr><tr><td style="text-align:left;"><strong>AAS</strong></td><td style="text-align:left;">角角边</td><td style="text-align:left;">两角相等且其中一个角的<strong>对边</strong>相等。</td></tr><tr><td style="text-align:left;"><strong>HL</strong></td><td style="text-align:left;">斜边直角边</td><td style="text-align:left;">仅限直角三角形：斜边和一条直角边对应相等。</td></tr></tbody></table><h3 id="【深度思考-为什么没有-ssa-】" tabindex="-1">【深度思考：为什么没有 SSA？】 <a class="header-anchor" href="#【深度思考-为什么没有-ssa-】" aria-label="Permalink to &quot;【深度思考：为什么没有 SSA？】&quot;">​</a></h3><p>如果你已知两边和其中一边的对角，你可能会画出两个截然不同的三角形。这就是著名的“SSA 陷阱”，在解题时必须格外小心。</p><hr><h1 id="第三篇-缩放-——-相似三角形的逻辑" tabindex="-1">第三篇：缩放 —— 相似三角形的逻辑 <a class="header-anchor" href="#第三篇-缩放-——-相似三角形的逻辑" aria-label="Permalink to &quot;第三篇：缩放 —— 相似三角形的逻辑&quot;">​</a></h1><h2 id="_3-1-相似的本质" tabindex="-1">3.1 相似的本质 <a class="header-anchor" href="#_3-1-相似的本质" aria-label="Permalink to &quot;3.1 相似的本质&quot;">​</a></h2><p>相似（Similarity）意味着形状相同，但大小成比例。它就像是在复印机里进行了缩放。</p><h2 id="_3-2-判定定理" tabindex="-1">3.2 判定定理 <a class="header-anchor" href="#_3-2-判定定理" aria-label="Permalink to &quot;3.2 判定定理&quot;">​</a></h2><ol><li><strong>AA (两角对应相等)</strong>：这是最实用的判定方法。只要两个角相等，第三个角必然相等（由内角和定理保证）。</li><li><strong>SAS (两边成比例且夹角相等)</strong>。</li><li><strong>SSS (三边成比例)</strong>。</li></ol><h2 id="_3-3-相似三角形的黄金性质" tabindex="-1">3.3 相似三角形的黄金性质 <a class="header-anchor" href="#_3-3-相似三角形的黄金性质" aria-label="Permalink to &quot;3.3 相似三角形的黄金性质&quot;">​</a></h2><p>如果 △ABC ∽ △DEF，比值为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span></span>，则：</p><ul><li><strong>周长比</strong>等于相似比 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span></span>。</li><li><strong>面积比</strong>等于相似比的平方 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>k</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">k^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>。</li></ul><hr><h1 id="第四篇-巅峰-——-勾股定理与中西方智慧" tabindex="-1">第四篇：巅峰 —— 勾股定理与中西方智慧 <a class="header-anchor" href="#第四篇-巅峰-——-勾股定理与中西方智慧" aria-label="Permalink to &quot;第四篇：巅峰 —— 勾股定理与中西方智慧&quot;">​</a></h1><h2 id="_4-1-勾股定理-pythagorean-theorem" tabindex="-1">4.1 勾股定理 (Pythagorean Theorem) <a class="header-anchor" href="#_4-1-勾股定理-pythagorean-theorem" aria-label="Permalink to &quot;4.1 勾股定理 (Pythagorean Theorem)&quot;">​</a></h2><p>在直角三角形中，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><msup><mi>b</mi><mn>2</mn></msup><mo>=</mo><msup><mi>c</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">a^2 + b^2 = c^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">b</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>。</p><h2 id="_4-2-勾股定理的经典证明" tabindex="-1">4.2 勾股定理的经典证明 <a class="header-anchor" href="#_4-2-勾股定理的经典证明" aria-label="Permalink to &quot;4.2 勾股定理的经典证明&quot;">​</a></h2><h3 id="_4-2-1-赵爽弦图-中国古代的巅峰" tabindex="-1">4.2.1 赵爽弦图 (中国古代的巅峰) <a class="header-anchor" href="#_4-2-1-赵爽弦图-中国古代的巅峰" aria-label="Permalink to &quot;4.2.1 赵爽弦图 (中国古代的巅峰)&quot;">​</a></h3><p>赵爽在《周髀算经》注中，利用四个全等的直角三角形拼成一个大正方形，中间围成一个小正方形。通过面积的割补：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>a</mi><mo>+</mo><mi>b</mi><msup><mo>)</mo><mn>2</mn></msup><mo>=</mo><mn>4</mn><mo>⋅</mo><mo>(</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac><mi>a</mi><mi>b</mi><mo>)</mo><mo>+</mo><msup><mi>c</mi><mn>2</mn></msup><mo>⇒</mo><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><mn>2</mn><mi>a</mi><mi>b</mi><mo>+</mo><msup><mi>b</mi><mn>2</mn></msup><mo>=</mo><mn>2</mn><mi>a</mi><mi>b</mi><mo>+</mo><msup><mi>c</mi><mn>2</mn></msup><mo>⇒</mo><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><msup><mi>b</mi><mn>2</mn></msup><mo>=</mo><msup><mi>c</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">(a+b)^2 = 4 \\cdot (\\frac{1}{2}ab) + c^2 \\Rightarrow a^2+2ab+b^2 = 2ab+c^2 \\Rightarrow a^2+b^2=c^2 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.32144em;"></span><span class="strut bottom" style="height:2.00744em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">a</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mclose"><span class="mclose">)</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mbin">⋅</span><span class="mopen">(</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mord mathit">a</span><span class="mord mathit">b</span><span class="mclose">)</span><span class="mbin">+</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">⇒</span><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathit">a</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord"><span class="mord mathit">b</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathit">a</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">⇒</span><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">b</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p>这种代数与几何的完美融合，比西方早了数百年。</p><h3 id="_4-2-2-加菲尔德证明-总统的几何课" tabindex="-1">4.2.2 加菲尔德证明 (总统的几何课) <a class="header-anchor" href="#_4-2-2-加菲尔德证明-总统的几何课" aria-label="Permalink to &quot;4.2.2 加菲尔德证明 (总统的几何课)&quot;">​</a></h3><p>美国第 20 任总统詹姆斯·加菲尔德曾给出一个精妙的梯形证明法： 利用两个全等的直角三角形拼成一个梯形。梯形面积既可以用公式算，也可以看作三个三角形面积之和。</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac><mo>(</mo><mi>a</mi><mo>+</mo><mi>b</mi><mo>)</mo><mo>(</mo><mi>a</mi><mo>+</mo><mi>b</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac><mi>a</mi><mi>b</mi><mo>+</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac><mi>a</mi><mi>b</mi><mo>+</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac><msup><mi>c</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\frac{1}{2}(a+b)(a+b) = \\frac{1}{2}ab + \\frac{1}{2}ab + \\frac{1}{2}c^2 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.32144em;"></span><span class="strut bottom" style="height:2.00744em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mopen">(</span><span class="mord mathit">a</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord mathit">a</span><span class="mbin">+</span><span class="mord mathit">b</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mord mathit">a</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mord mathit">a</span><span class="mord mathit">b</span><span class="mbin">+</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.413em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p>消去 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{1}{2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.845108em;"></span><span class="strut bottom" style="height:1.190108em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span> 并展开后，同样得到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><msup><mi>b</mi><mn>2</mn></msup><mo>=</mo><msup><mi>c</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">a^2+b^2=c^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">b</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>。</p><hr><h1 id="第五篇-相似与比例的进阶" tabindex="-1">第五篇：相似与比例的进阶 <a class="header-anchor" href="#第五篇-相似与比例的进阶" aria-label="Permalink to &quot;第五篇：相似与比例的进阶&quot;">​</a></h1><h2 id="_5-1-射影定理-euclidean-theorem" tabindex="-1">5.1 射影定理 (Euclidean Theorem) <a class="header-anchor" href="#_5-1-射影定理-euclidean-theorem" aria-label="Permalink to &quot;5.1 射影定理 (Euclidean Theorem)&quot;">​</a></h2><p>在直角三角形 ABC 中，CD 是斜边 AB 上的高，则：</p><ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi><msup><mi>D</mi><mn>2</mn></msup><mo>=</mo><mi>A</mi><mi>D</mi><mo>⋅</mo><mi>D</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">CD^2 = AD \\cdot DB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mbin">⋅</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> （高是两段投影的比例中项）。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><msup><mi>C</mi><mn>2</mn></msup><mo>=</mo><mi>A</mi><mi>D</mi><mo>⋅</mo><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AC^2 = AD \\cdot AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mbin">⋅</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> （直角边是其投影与斜边的比例中项）。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><msup><mi>C</mi><mn>2</mn></msup><mo>=</mo><mi>B</mi><mi>D</mi><mo>⋅</mo><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">BC^2 = BD \\cdot AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.8141079999999999em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mbin">⋅</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span>。</li></ul><h2 id="_5-2-比例线段的黄金分割" tabindex="-1">5.2 比例线段的黄金分割 <a class="header-anchor" href="#_5-2-比例线段的黄金分割" aria-label="Permalink to &quot;5.2 比例线段的黄金分割&quot;">​</a></h2><p>在某些特殊的相似三角形中，边长的比例恰好等于黄金比例 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><msqrt><mrow><mn>5</mn></mrow></msqrt><mo>−</mo><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{\\sqrt{5}-1}{2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.054554em;"></span><span class="strut bottom" style="height:1.399554em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.08650571428571419em;"><span class="style-wrap reset-scriptstyle scriptstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span><span class="mord scriptstyle cramped"><span class="mord mathrm">5</span></span></span><span style="top:-0.8293628571428571em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span><span class="reset-scriptstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1.4285714285714286em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>。这在古希腊建筑和艺术中被视为美的准则。</p><h2 id="_5-3-角平分线定理的证明" tabindex="-1">5.3 角平分线定理的证明 <a class="header-anchor" href="#_5-3-角平分线定理的证明" aria-label="Permalink to &quot;5.3 角平分线定理的证明&quot;">​</a></h2><p>角平分线定理：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mi>A</mi><mi>B</mi></mrow><mrow><mi>A</mi><mi>C</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>B</mi><mi>D</mi></mrow><mrow><mi>D</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{AB}{AC} = \\frac{BD}{DC}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.872331em;"></span><span class="strut bottom" style="height:1.217331em;vertical-align:-0.345em;"></span><span class="base textstyle uncramped"><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.345em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.394em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.02778em;">D</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span>。 证明思路：</p><ol><li>过点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 作 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi><mi>E</mi><mi mathvariant="normal">/</mi><mi mathvariant="normal">/</mi><mi>A</mi><mi>D</mi></mrow><annotation encoding="application/x-tex">CE // AD</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathrm">/</span><span class="mord mathrm">/</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span></span></span></span> 交 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mi>A</mi></mrow><annotation encoding="application/x-tex">BA</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit">A</span></span></span></span> 的延长线于点 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>E</mi></mrow><annotation encoding="application/x-tex">E</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span>。</li><li>利用平行线的内错角和同位角相等，证明 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>C</mi><mi>E</mi></mrow><annotation encoding="application/x-tex">\\triangle ACE</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span> 是等腰三角形，即 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>E</mi><mo>=</mo><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AE = AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。</li><li>利用平行线分线段成比例定理：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mi>A</mi><mi mathvariant="normal">/</mi><mi>A</mi><mi>E</mi><mo>=</mo><mi>B</mi><mi>D</mi><mi mathvariant="normal">/</mi><mi>D</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">BA/AE = BD/DC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit">A</span><span class="mord mathrm">/</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mrel">=</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathrm">/</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。</li><li>替换 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>E</mi></mrow><annotation encoding="application/x-tex">AE</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span> 为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>，得证。</li></ol><h2 id="_5-4-塞瓦定理-ceva-s-theorem-——-共点的奥秘" tabindex="-1">5.4 塞瓦定理 (Ceva&#39;s Theorem) —— 共点的奥秘 <a class="header-anchor" href="#_5-4-塞瓦定理-ceva-s-theorem-——-共点的奥秘" aria-label="Permalink to &quot;5.4 塞瓦定理 (Ceva&#39;s Theorem) —— 共点的奥秘&quot;">​</a></h2><p>由意大利数学家塞瓦在 1678 年提出。它为判断三角形三条线段是否交于一点提供了充要条件。 在 △ABC 中，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mo separator="true">,</mo><mi>E</mi><mo separator="true">,</mo><mi>F</mi></mrow><annotation encoding="application/x-tex">D, E, F</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.13889em;">F</span></span></span></span> 分别是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mi>C</mi><mo separator="true">,</mo><mi>C</mi><mi>A</mi><mo separator="true">,</mo><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">BC, CA, AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit">A</span><span class="mpunct">,</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 上的点，若线段 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>D</mi><mo separator="true">,</mo><mi>B</mi><mi>E</mi><mo separator="true">,</mo><mi>C</mi><mi>F</mi></mrow><annotation encoding="application/x-tex">AD, BE, CF</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.13889em;">F</span></span></span></span> 交于一点，则：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mfrac><mrow><mi>A</mi><mi>F</mi></mrow><mrow><mi>F</mi><mi>B</mi></mrow></mfrac><mo>⋅</mo><mfrac><mrow><mi>B</mi><mi>D</mi></mrow><mrow><mi>D</mi><mi>C</mi></mrow></mfrac><mo>⋅</mo><mfrac><mrow><mi>C</mi><mi>E</mi></mrow><mrow><mi>E</mi><mi>A</mi></mrow></mfrac><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\frac{AF}{FB} \\cdot \\frac{BD}{DC} \\cdot \\frac{CE}{EA} = 1 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.36033em;"></span><span class="strut bottom" style="height:2.04633em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.13889em;">F</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.02778em;">D</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">⋅</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathit">A</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span></span></p><h2 id="_5-4-梅涅劳斯定理-menelaus-theorem-——-共线的奥秘" tabindex="-1">5.4 梅涅劳斯定理 (Menelaus&#39; Theorem) —— 共线的奥秘 <a class="header-anchor" href="#_5-4-梅涅劳斯定理-menelaus-theorem-——-共线的奥秘" aria-label="Permalink to &quot;5.4 梅涅劳斯定理 (Menelaus&#39; Theorem) —— 共线的奥秘&quot;">​</a></h2><p>与塞瓦定理相对应，它用于判定三个点是否在同一条直线上。这两个定理是竞赛几何中处理线段比例关系的“双子星”。</p><hr><h1 id="第六篇-几何的边界-——-非欧几何中的三角形" tabindex="-1">第六篇：几何的边界 —— 非欧几何中的三角形 <a class="header-anchor" href="#第六篇-几何的边界-——-非欧几何中的三角形" aria-label="Permalink to &quot;第六篇：几何的边界 —— 非欧几何中的三角形&quot;">​</a></h1><p>当我们走出欧几里得的平坦世界，三角形的定理会发生翻天覆地的变化。</p><h2 id="_6-1-球面几何-elliptic-geometry" tabindex="-1">6.1 球面几何 (Elliptic Geometry) <a class="header-anchor" href="#_6-1-球面几何-elliptic-geometry" aria-label="Permalink to &quot;6.1 球面几何 (Elliptic Geometry)&quot;">​</a></h2><p>在地球表面画一个三角形：</p><ul><li><strong>内角和</strong>：始终大于 180°。</li><li><strong>全等判定</strong>：甚至存在 AAA 判定全等（因为大小和角度不再解耦）。</li></ul><h2 id="_6-2-双曲几何-hyperbolic-geometry" tabindex="-1">6.2 双曲几何 (Hyperbolic Geometry) <a class="header-anchor" href="#_6-2-双曲几何-hyperbolic-geometry" aria-label="Permalink to &quot;6.2 双曲几何 (Hyperbolic Geometry)&quot;">​</a></h2><p>在类似马鞍面的空间中：</p><ul><li><strong>内角和</strong>：始终小于 180°。</li><li><strong>平行公理</strong>：通过直线外一点，可以作无数条平行线。</li></ul><p>这些进阶知识告诉我们：定理的正确性取决于我们所在的“空间规则”。</p><hr><h1 id="第七篇-全等证明中的辅助线技巧" tabindex="-1">第七篇：全等证明中的辅助线技巧 <a class="header-anchor" href="#第七篇-全等证明中的辅助线技巧" aria-label="Permalink to &quot;第七篇：全等证明中的辅助线技巧&quot;">​</a></h1><p>几何证明中，辅助线往往是“点睛之笔”。</p><ol><li><strong>倍长中线</strong>：将三角形的中线延长一倍，构造全等三角形（构造平行四边形）。</li><li><strong>截长补短</strong>：在已知线段的和差关系时，通过截取或延长构造全等三角形。</li><li><strong>过顶点作平行线</strong>：将分散的角或线段集中到一起。</li></ol><hr><h1 id="第七篇-实战演练与逻辑拆解" tabindex="-1">第七篇：实战演练与逻辑拆解 <a class="header-anchor" href="#第七篇-实战演练与逻辑拆解" aria-label="Permalink to &quot;第七篇：实战演练与逻辑拆解&quot;">​</a></h1><h3 id="【经典例题-1-外角的妙用】" tabindex="-1">【经典例题 1：外角的妙用】 <a class="header-anchor" href="#【经典例题-1-外角的妙用】" aria-label="Permalink to &quot;【经典例题 1：外角的妙用】&quot;">​</a></h3><p>已知 ∠A = 40°，∠B = 60°，求 ∠C 的补角（外角）。</p><p><strong>解析</strong>： 根据外角定理，外角 = ∠A + ∠B = 40° + 60° = 100°。 <em>不需要先算出 ∠C，直接一步到位！</em></p><h3 id="【经典例题-2-全等证明实战】" tabindex="-1">【经典例题 2：全等证明实战】 <a class="header-anchor" href="#【经典例题-2-全等证明实战】" aria-label="Permalink to &quot;【经典例题 2：全等证明实战】&quot;">​</a></h3><p>已知 AB = AC，AD 是 BC 的中线。求证：AD ⊥ BC。</p><p><strong>证明</strong>：</p><ol><li>在 △ABD 和 △ACD 中： <ul><li>AB = AC (已知)</li><li>BD = CD (中线定义)</li><li>AD = AD (公共边)</li></ul></li><li>根据 <strong>SSS</strong>，△ABD ≌ △ACD。</li><li>因此，∠ADB = ∠ADC。</li><li>又因为 ∠ADB + ∠ADC = 180°（平角）。</li><li>所以 ∠ADB = 90°，即 AD ⊥ BC。</li></ol><hr><h1 id="第七篇-生活中的定理" tabindex="-1">第七篇：生活中的定理 <a class="header-anchor" href="#第七篇-生活中的定理" aria-label="Permalink to &quot;第七篇：生活中的定理&quot;">​</a></h1><ol><li><strong>木工测直角</strong>：木工师傅会用 30cm, 40cm, 50cm 的木条拼成三角形，确保柜子是方的。</li><li><strong>影子测量法</strong>：泰勒斯曾利用相似三角形，通过测量影子的长度算出了金字塔的高度。</li><li><strong>视觉透视</strong>：在绘画和摄影中，近大远小的透视效果本质上就是相似三角形的应用。</li></ol><hr><h1 id="第九篇-综合练习与能力提升" tabindex="-1">第九篇：综合练习与能力提升 <a class="header-anchor" href="#第九篇-综合练习与能力提升" aria-label="Permalink to &quot;第九篇：综合练习与能力提升&quot;">​</a></h1><h3 id="【基础关】" tabindex="-1">【基础关】 <a class="header-anchor" href="#【基础关】" aria-label="Permalink to &quot;【基础关】&quot;">​</a></h3><ol><li><strong>题目</strong>：已知 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi><mo>≅</mo><mi mathvariant="normal">△</mi><mi>D</mi><mi>E</mi><mi>F</mi></mrow><annotation encoding="application/x-tex">\\triangle ABC \\cong \\triangle DEF</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">≅</span><span class="mord mathrm">△</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathit" style="margin-right:0.13889em;">F</span></span></span></span>，若 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>B</mi><mo>=</mo><mn>5</mn><mo separator="true">,</mo><mi>B</mi><mi>C</mi><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">AB=5, BC=6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>，则 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mi>E</mi><mo>=</mo></mrow><annotation encoding="application/x-tex">DE=</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mrel">=</span></span></span></span> ______，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>E</mi><mi>F</mi><mo>=</mo></mrow><annotation encoding="application/x-tex">EF=</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mrel">=</span></span></span></span> ______。 <strong>解答</strong>：由全等性质知对应边相等，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mi>E</mi><mo>=</mo><mi>A</mi><mi>B</mi><mo>=</mo><mn>5</mn><mo separator="true">,</mo><mi>E</mi><mi>F</mi><mo>=</mo><mi>B</mi><mi>C</mi><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">DE=AB=5, EF=BC=6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mrel">=</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>。</li><li><strong>题目</strong>：若一个直角三角形的两边长分别为 3 和 4，求第三边的长度。 <strong>解答</strong>：分两种情况： <ul><li>3 和 4 是直角边：斜边 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msqrt><mrow><msup><mn>3</mn><mn>2</mn></msup><mo>+</mo><msup><mn>4</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">\\sqrt{3^2+4^2} = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.913389em;"></span><span class="strut bottom" style="height:1.04em;vertical-align:-0.12661100000000008em;"></span><span class="base textstyle uncramped"><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.07338899999999993em;"><span class="style-wrap reset-textstyle textstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord"><span class="mord mathrm">3</span><span class="vlist"><span style="top:-0.289em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathrm">4</span><span class="vlist"><span style="top:-0.289em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span><span style="top:-0.8333889999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>。</li><li>4 是斜边，3 是直角边：另一条直角边 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msqrt><mrow><msup><mn>4</mn><mn>2</mn></msup><mo>−</mo><msup><mn>3</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mrow><mn>7</mn></mrow></msqrt></mrow><annotation encoding="application/x-tex">\\sqrt{4^2-3^2} = \\sqrt{7}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.913389em;"></span><span class="strut bottom" style="height:1.046169em;vertical-align:-0.13277999999999995em;"></span><span class="base textstyle uncramped"><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.07338899999999993em;"><span class="style-wrap reset-textstyle textstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord"><span class="mord mathrm">4</span><span class="vlist"><span style="top:-0.289em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="mord"><span class="mord mathrm">3</span><span class="vlist"><span style="top:-0.289em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span><span style="top:-0.8333889999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.06722000000000006em;"><span class="style-wrap reset-textstyle textstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord mathrm">7</span></span></span><span style="top:-0.8272200000000001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span></span></span></span>。 <strong>结论</strong>：5 或 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msqrt><mrow><mn>7</mn></mrow></msqrt></mrow><annotation encoding="application/x-tex">\\sqrt{7}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.9072200000000001em;"></span><span class="strut bottom" style="height:1.04em;vertical-align:-0.13277999999999995em;"></span><span class="base textstyle uncramped"><span class="sqrt mord"><span class="sqrt-sign" style="top:-0.06722000000000006em;"><span class="style-wrap reset-textstyle textstyle uncramped">√</span></span><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="mord textstyle cramped"><span class="mord mathrm">7</span></span></span><span style="top:-0.8272200000000001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped sqrt-line"></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span></span></span></span>。</li></ul></li><li><strong>题目</strong>：判断：三边分别对应成比例的两个三角形一定相似吗？ <strong>解答</strong>：是的。根据 SSS 相似判定定理。</li></ol><h3 id="【进阶关】" tabindex="-1">【进阶关】 <a class="header-anchor" href="#【进阶关】" aria-label="Permalink to &quot;【进阶关】&quot;">​</a></h3><ol start="4"><li><strong>题目</strong>：在直角三角形 ABC 中，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">∠</mi><mi>C</mi><mo>=</mo><mn>9</mn><msup><mn>0</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">\\angle C = 90^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69224em;"></span><span class="strut bottom" style="height:0.69224em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">∠</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord"><span class="mord mathrm">0</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord">∘</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>，斜边 AB 上的高 CD 分斜边为 2cm 和 8cm，求 CD 的长度。 <strong>解答</strong>：利用射影定理 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi><msup><mi>D</mi><mn>2</mn></msup><mo>=</mo><mi>A</mi><mi>D</mi><mo>⋅</mo><mi>D</mi><mi>B</mi><mo>=</mo><mn>2</mn><mo>×</mo><mn>8</mn><mo>=</mo><mn>1</mn><mn>6</mn><mo>⇒</mo><mi>C</mi><mi>D</mi><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">CD^2 = AD \\cdot DB = 2 \\times 8 = 16 \\Rightarrow CD = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mbin">⋅</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mrel">⇒</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>cm。</li><li><strong>题目</strong>：已知 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi><mo>∼</mo><mi mathvariant="normal">△</mi><msup><mi>A</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><msup><mi>B</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><msup><mi>C</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup></mrow><annotation encoding="application/x-tex">\\triangle ABC \\sim \\triangle A&#39;B&#39;C&#39;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.751892em;"></span><span class="strut bottom" style="height:0.946332em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">∼</span><span class="mord mathrm">△</span><span class="mord"><span class="mord mathit">A</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>，相似比为 2:3。若 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">\\triangle ABC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 的面积为 16cm²，求 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><msup><mi>A</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><msup><mi>B</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><msup><mi>C</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup></mrow><annotation encoding="application/x-tex">\\triangle A&#39;B&#39;C&#39;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.751892em;"></span><span class="strut bottom" style="height:0.946332em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord"><span class="mord mathit">A</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span> 的面积。 <strong>解答</strong>：面积比等于相似比的平方，即 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mi mathvariant="normal">/</mi><mn>3</mn><msup><mo>)</mo><mn>2</mn></msup><mo>=</mo><mn>4</mn><mo>:</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">(2/3)^2 = 4:9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">/</span><span class="mord mathrm">3</span><span class="mclose"><span class="mclose">)</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mrel">:</span><span class="mord mathrm">9</span></span></span></span>。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mi mathvariant="normal">/</mi><msup><mi>S</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><mo>=</mo><mn>4</mn><mi mathvariant="normal">/</mi><mn>9</mn><mo>⇒</mo><msup><mi>S</mi><mrow><mi mathvariant="normal">′</mi></mrow></msup><mo>=</mo><mn>1</mn><mn>6</mn><mo>×</mo><mn>9</mn><mi mathvariant="normal">/</mi><mn>4</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">16 / S&#39; = 4/9 \\Rightarrow S&#39; = 16 \\times 9 / 4 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.751892em;"></span><span class="strut bottom" style="height:1.001892em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mord mathrm">/</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">/</span><span class="mord mathrm">9</span><span class="mrel">⇒</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">′</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">9</span><span class="mord mathrm">/</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>cm²。</li></ol><h3 id="【挑战关】" tabindex="-1">【挑战关】 <a class="header-anchor" href="#【挑战关】" aria-label="Permalink to &quot;【挑战关】&quot;">​</a></h3><ol start="6"><li><strong>证明题</strong>：证明直角三角形斜边上的中线等于斜边的一半。 <strong>证明思路</strong>：将直角三角形补全为一个矩形。矩形的对角线相等且互相平分。直角三角形的斜边就是矩形的一条对角线，而斜边上的中线就是对角线的一半。</li><li><strong>竞赛题</strong>：在 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">\\triangle ABC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 中，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mo separator="true">,</mo><mi>E</mi></mrow><annotation encoding="application/x-tex">D, E</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span> 分别在 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>B</mi><mo separator="true">,</mo><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AB, AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mpunct">,</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 上，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mi>E</mi><mi mathvariant="normal">/</mi><mi mathvariant="normal">/</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">DE // BC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathrm">/</span><span class="mord mathrm">/</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。若 S_{\\triangle ADE} : S_{\\text{梯形 DBCE}} = 1 : 3，求 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>D</mi><mo>:</mo><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AD : AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mrel">:</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 的值。 <strong>解答</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>S</mi><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>D</mi><mi>E</mi></mrow></msub><mi mathvariant="normal">/</mi><msub><mi>S</mi><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi></mrow></msub><mo>=</mo><mn>1</mn><mi mathvariant="normal">/</mi><mo>(</mo><mn>1</mn><mo>+</mo><mn>3</mn><mo>)</mo><mo>=</mo><mn>1</mn><mi mathvariant="normal">/</mi><mn>4</mn></mrow><annotation encoding="application/x-tex">S_{\\triangle ADE} / S_{\\triangle ABC} = 1 / (1+3) = 1/4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mathrm">/</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.05764em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">/</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">/</span><span class="mord mathrm">4</span></span></span></span>。因为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>D</mi><mi>E</mi><mi mathvariant="normal">/</mi><mi mathvariant="normal">/</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">DE // BC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mord mathrm">/</span><span class="mord mathrm">/</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>，所以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">△</mi><mi>A</mi><mi>D</mi><mi>E</mi><mo>∼</mo><mi mathvariant="normal">△</mi><mi>A</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">\\triangle ADE \\sim \\triangle ABC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.8888799999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="mrel">∼</span><span class="mord mathrm">△</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。面积比等于相似比的平方，即 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>A</mi><mi>D</mi><mi mathvariant="normal">/</mi><mi>A</mi><mi>B</mi><msup><mo>)</mo><mn>2</mn></msup><mo>=</mo><mn>1</mn><mi mathvariant="normal">/</mi><mn>4</mn><mo>⇒</mo><mi>A</mi><mi>D</mi><mi mathvariant="normal">/</mi><mi>A</mi><mi>B</mi><mo>=</mo><mn>1</mn><mi mathvariant="normal">/</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">(AD/AB)^2 = 1/4 \\Rightarrow AD/AB = 1/2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathrm">/</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mclose"><span class="mclose">)</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">/</span><span class="mord mathrm">4</span><span class="mrel">⇒</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.02778em;">D</span><span class="mord mathrm">/</span><span class="mord mathit">A</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">/</span><span class="mord mathrm">2</span></span></span></span>。</li></ol><hr><h1 id="第十篇-定理知识图谱总结" tabindex="-1">第十篇：定理知识图谱总结 <a class="header-anchor" href="#第十篇-定理知识图谱总结" aria-label="Permalink to &quot;第十篇：定理知识图谱总结&quot;">​</a></h1><ul><li><strong>角度类</strong>：内角和 180°、外角定理。</li><li><strong>同构类</strong>：全等判定 (SSS, SAS, ASA, AAS, HL)。</li><li><strong>缩放类</strong>：相似判定 (AA, SAS, SSS)、面积比=相似比平方。</li><li><strong>度量类</strong>：勾股定理 (<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msup><mi>a</mi><mn>2</mn></msup><mo>+</mo><msup><mi>b</mi><mn>2</mn></msup><mo>=</mo><msup><mi>c</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">a^2+b^2=c^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.897438em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">b</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit">c</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>)、射影定理。</li><li><strong>进阶类</strong>：塞瓦定理、梅涅劳斯定理。</li></ul><hr><h1 id="第十一篇-中英文术语对照表-glossary" tabindex="-1">第十一篇：中英文术语对照表 (Glossary) <a class="header-anchor" href="#第十一篇-中英文术语对照表-glossary" aria-label="Permalink to &quot;第十一篇：中英文术语对照表 (Glossary)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">中文术语</th><th style="text-align:left;">英文术语</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定理</strong></td><td style="text-align:left;">Theorem</td><td style="text-align:left;">经过逻辑证明的真命题。</td></tr><tr><td style="text-align:left;"><strong>公理</strong></td><td style="text-align:left;">Axiom</td><td style="text-align:left;">不证自明的基本事实（如欧几里得五大公理）。</td></tr><tr><td style="text-align:left;"><strong>全等</strong></td><td style="text-align:left;">Congruence</td><td style="text-align:left;">形状和大小完全相同。</td></tr><tr><td style="text-align:left;"><strong>相似</strong></td><td style="text-align:left;">Similarity</td><td style="text-align:left;">形状相同，大小成比例。</td></tr><tr><td style="text-align:left;"><strong>对应边</strong></td><td style="text-align:left;">Corresponding Sides</td><td style="text-align:left;">在全等或相似变换中位置对应的边。</td></tr><tr><td style="text-align:left;"><strong>辅助线</strong></td><td style="text-align:left;">Auxiliary Line</td><td style="text-align:left;">为了证明而额外画出的线段。</td></tr><tr><td style="text-align:left;"><strong>逆定理</strong></td><td style="text-align:left;">Converse Theorem</td><td style="text-align:left;">交换原命题的条件和结论所得的新命题。</td></tr></tbody></table><hr><h1 id="第十二篇-高阶思考与几何视野" tabindex="-1">第十二篇：高阶思考与几何视野 <a class="header-anchor" href="#第十二篇-高阶思考与几何视野" aria-label="Permalink to &quot;第十二篇：高阶思考与几何视野&quot;">​</a></h1><ol><li><strong>平行公理的挑战</strong>：如果三角形内角和不等于 180°，会发生什么？这正是非欧几何的起源，也是广义相对论中时空弯曲的数学基础。</li><li><strong>尺规作图的局限</strong>：有些三角形是画不出来的吗？比如“三等分任意角”是无法用直尺和圆规完成的。</li><li><strong>计算机辅助证明</strong>：现在的数学家利用计算机（如 Coq 或 Lean）来验证几何证明的逻辑严密性，确保没有任何人为漏洞。</li></ol><hr><h1 id="第十三篇-现代视野-——-ai-与几何证明" tabindex="-1">第十三篇：现代视野 —— AI 与几何证明 <a class="header-anchor" href="#第十三篇-现代视野-——-ai-与几何证明" aria-label="Permalink to &quot;第十三篇：现代视野 —— AI 与几何证明&quot;">​</a></h1><h2 id="_13-1-机器证明的崛起" tabindex="-1">13.1 机器证明的崛起 <a class="header-anchor" href="#_13-1-机器证明的崛起" aria-label="Permalink to &quot;13.1 机器证明的崛起&quot;">​</a></h2><p>从 20 世纪 50 年代开始，数学家（如中国的吴文俊院士）提出了“吴方法”，开创了利用计算机自动证明几何定理的新纪元。现在的 AI（如 Google DeepMind 的 AlphaGeometry）已经能够以奥数选手的水平解决复杂的三角形几何题。</p><h2 id="_13-2-逻辑的普适性" tabindex="-1">13.2 逻辑的普适性 <a class="header-anchor" href="#_13-2-逻辑的普适性" aria-label="Permalink to &quot;13.2 逻辑的普适性&quot;">​</a></h2><p>几何证明教会了人类最基础的逻辑范式：<strong>已知 → 推导 → 结论</strong>。这种思维方式不仅在数学中适用，在法学证明、代码调试和科学实验中都是核心逻辑。</p><hr><h1 id="第十五篇-你知道吗-——-三角形定理的趣味冷知识" tabindex="-1">第十五篇：你知道吗？ —— 三角形定理的趣味冷知识 <a class="header-anchor" href="#第十五篇-你知道吗-——-三角形定理的趣味冷知识" aria-label="Permalink to &quot;第十五篇：你知道吗？ —— 三角形定理的趣味冷知识&quot;">​</a></h1><ol><li><strong>370 种证明</strong>：勾股定理是世界上证明方法最多的定理。从达芬奇到美国总统加菲尔德，各行各业的人都曾为它贡献过证明。</li><li><strong>“埃及绳”</strong>：古埃及人使用打有 12 个等距结的绳子（3+4+5=12），以此在工地上围出直角，这种做法延续了数千年。</li><li><strong>相似三角形与日食</strong>：古代数学家通过月球和太阳在天空中的视直径相等（相似三角形模型），在没有望远镜的情况下估算出了日地距离的比例。</li></ol><hr><h1 id="第十六篇-动手小实验-——-验证内角和" tabindex="-1">第十六篇：动手小实验 —— 验证内角和 <a class="header-anchor" href="#第十六篇-动手小实验-——-验证内角和" aria-label="Permalink to &quot;第十六篇：动手小实验 —— 验证内角和&quot;">​</a></h1><p><strong>实验步骤</strong>：</p><ol><li>在纸上画一个任意形状的大三角形。</li><li>用剪刀把三角形的三个角剪下来。</li><li>将三个角的顶点拼在一起。 <strong>观察</strong>：你会发现三个角正好拼成一条直线。 <strong>深度思考</strong>：如果你的纸是弯曲的（比如在一个皮球上），这个实验还能成功吗？</li></ol><hr><h1 id="第十七篇-推荐阅读与延伸学习" tabindex="-1">第十七篇：推荐阅读与延伸学习 <a class="header-anchor" href="#第十七篇-推荐阅读与延伸学习" aria-label="Permalink to &quot;第十七篇：推荐阅读与延伸学习&quot;">​</a></h1><ul><li><strong>书籍</strong>：《几何的本质》（M.C. Escher 相关几何研究）。</li><li><strong>人物</strong>：吴文俊 —— 了解中国在自动证明领域的卓越贡献。</li><li><strong>工具</strong>：Lean 4 —— 尝试用代码写出严谨的几何证明。</li></ul><hr><h1 id="结语-逻辑的胜利" tabindex="-1">结语：逻辑的胜利 <a class="header-anchor" href="#结语-逻辑的胜利" aria-label="Permalink to &quot;结语：逻辑的胜利&quot;">​</a></h1><p>定理是几何学的骨架，证明是几何学的血肉。当我们通过已知条件一步步推导出结论时，我们感受到的不仅是数学的严谨，更是人类理性的光辉。</p><p>希望通过这篇文章，你不再畏惧几何证明，而是能享受那份“拨开云雾见青天”的逻辑快感。</p><hr><h1 id="课后挑战-self-challenge" tabindex="-1">课后挑战 (Self-Challenge) <a class="header-anchor" href="#课后挑战-self-challenge" aria-label="Permalink to &quot;课后挑战 (Self-Challenge)&quot;">​</a></h1><ol><li><strong>动手画图</strong>：尝试用尺规作图法，只用圆规和直尺，画出一个与已知三角形全等的图形。</li><li><strong>自主证明</strong>：尝试证明“等边对等角”（等腰三角形的底角相等）。</li><li><strong>深度探索</strong>：如果把三角形放在球面上（如地球表面），内角和还会是 180° 吗？为什么？</li></ol><hr><blockquote><p><strong>版权声明</strong>：本文为《儒生的技术生活》原创系列教程，转载请注明出处。</p></blockquote>',126)])])}const g=a(p,[["render",i]]);export{y as __pageData,g as default};
